using AutoMapper;
using Microsoft.Data.SqlClient;
using Orders.Dal;
using Orders.Domain;

namespace Orders.Bll;

public interface ICustomerService { Task<IReadOnlyList<CustomerDto>> GetAllAsync(CancellationToken ct); Task<CustomerDto> GetAsync(Guid id,CancellationToken ct); Task<CustomerDto> CreateAsync(CustomerWriteDto dto,CancellationToken ct); Task<CustomerDto> UpdateAsync(Guid id,CustomerWriteDto dto,CancellationToken ct); Task DeleteAsync(Guid id,CancellationToken ct); }
public interface IProductService { Task<IReadOnlyList<ProductDto>> GetAllAsync(CancellationToken ct); Task<ProductDto> GetAsync(Guid id,CancellationToken ct); Task<ProductDto> CreateAsync(ProductWriteDto dto,CancellationToken ct); Task<ProductDto> UpdateAsync(Guid id,ProductWriteDto dto,CancellationToken ct); Task DeleteAsync(Guid id,CancellationToken ct); }
public interface IOrderService { Task<IReadOnlyList<OrderDto>> GetAllAsync(CancellationToken ct); Task<OrderDto> GetAsync(Guid id,CancellationToken ct); Task<OrderDto> CreateAsync(CreateOrderDto dto,CancellationToken ct); Task<OrderDto> ChangeStatusAsync(Guid id,UpdateOrderStatusDto dto,CancellationToken ct); Task DeleteAsync(Guid id,CancellationToken ct); }

public sealed class CustomerService(IUnitOfWork uow,IMapper mapper) : ICustomerService
{
 public async Task<IReadOnlyList<CustomerDto>> GetAllAsync(CancellationToken ct)=>mapper.Map<IReadOnlyList<CustomerDto>>(await uow.Customers.GetAllAsync(ct));
 public async Task<CustomerDto> GetAsync(Guid id,CancellationToken ct)=>mapper.Map<CustomerDto>(await uow.Customers.GetByIdAsync(id,ct)??throw new EntityNotFoundException($"Customer {id} was not found."));
 public async Task<CustomerDto> CreateAsync(CustomerWriteDto d,CancellationToken ct){if(await uow.Customers.EmailExistsAsync(d.Email,null,ct))throw new BusinessConflictException("A customer with this email already exists.");try{return mapper.Map<CustomerDto>(await uow.Customers.AddAsync(new Customer{CustomerId=Guid.NewGuid(),Email=d.Email.Trim(),DisplayName=d.DisplayName.Trim()},ct));}catch(SqlException e) when(e.Number is 2601 or 2627){throw new BusinessConflictException("A customer with this email already exists.");}}
 public async Task<CustomerDto> UpdateAsync(Guid id,CustomerWriteDto d,CancellationToken ct){var x=await uow.Customers.GetByIdAsync(id,ct)??throw new EntityNotFoundException($"Customer {id} was not found.");if(await uow.Customers.EmailExistsAsync(d.Email,id,ct))throw new BusinessConflictException("A customer with this email already exists.");x.Email=d.Email.Trim();x.DisplayName=d.DisplayName.Trim();if(!string.IsNullOrWhiteSpace(d.RowVersion))x.RowVer=DecodeVersion(d.RowVersion);try{if(await uow.Customers.UpdateAsync(x,ct)==0)throw new BusinessConflictException("Customer changed since it was read; reload and retry.");}catch(SqlException e)when(e.Number is 2601 or 2627){throw new BusinessConflictException("A customer with this email already exists.");}return await GetAsync(id,ct);}
 public async Task DeleteAsync(Guid id,CancellationToken ct){if(await uow.Customers.DeleteAsync(id,ct)==0)throw new EntityNotFoundException($"Customer {id} was not found.");}
 internal static byte[] DecodeVersion(string value){try{return Convert.FromBase64String(value);}catch(FormatException){throw new DomainValidationException("RowVersion must be valid Base64.");}}
}
public sealed class ProductService(IUnitOfWork uow,IMapper mapper) : IProductService
{
 public async Task<IReadOnlyList<ProductDto>> GetAllAsync(CancellationToken ct)=>mapper.Map<IReadOnlyList<ProductDto>>(await uow.Products.GetAllAsync(ct));
 public async Task<ProductDto> GetAsync(Guid id,CancellationToken ct)=>mapper.Map<ProductDto>(await uow.Products.GetByIdAsync(id,ct)??throw new EntityNotFoundException($"Product {id} was not found."));
 public async Task<ProductDto> CreateAsync(ProductWriteDto d,CancellationToken ct){if(await uow.Products.SkuExistsAsync(d.Sku,null,ct))throw new BusinessConflictException("A product with this SKU already exists.");try{return mapper.Map<ProductDto>(await uow.Products.AddAsync(new ProductSnapshot{ProductId=Guid.NewGuid(),ProductName=d.ProductName.Trim(),Sku=d.Sku.Trim(),CurrentPrice=d.CurrentPrice},ct));}catch(SqlException e)when(e.Number is 2601 or 2627){throw new BusinessConflictException("A product with this SKU already exists.");}}
 public async Task<ProductDto> UpdateAsync(Guid id,ProductWriteDto d,CancellationToken ct){var x=await uow.Products.GetByIdAsync(id,ct)??throw new EntityNotFoundException($"Product {id} was not found.");if(await uow.Products.SkuExistsAsync(d.Sku,id,ct))throw new BusinessConflictException("A product with this SKU already exists.");x.ProductName=d.ProductName.Trim();x.Sku=d.Sku.Trim();x.CurrentPrice=d.CurrentPrice;if(!string.IsNullOrWhiteSpace(d.RowVersion))x.RowVer=CustomerService.DecodeVersion(d.RowVersion);try{if(await uow.Products.UpdateAsync(x,ct)==0)throw new BusinessConflictException("Product changed since it was read; reload and retry.");}catch(SqlException e)when(e.Number is 2601 or 2627){throw new BusinessConflictException("A product with this SKU already exists.");}return await GetAsync(id,ct);}
 public async Task DeleteAsync(Guid id,CancellationToken ct){if(await uow.Products.DeleteAsync(id,ct)==0)throw new EntityNotFoundException($"Product {id} was not found.");}
}
public sealed class OrderService(IUnitOfWork uow,IMapper mapper) : IOrderService
{
 public async Task<IReadOnlyList<OrderDto>> GetAllAsync(CancellationToken ct){var orders=await uow.Orders.GetAllAsync(ct);var result=new List<OrderDto>();foreach(var order in orders)result.Add(await MapOrder(order,ct));return result;}
 public async Task<OrderDto> GetAsync(Guid id,CancellationToken ct)=>await MapOrder(await uow.Orders.GetWithCustomerAsync(id,ct)??throw new EntityNotFoundException($"Order {id} was not found."),ct);
 private async Task<OrderDto> MapOrder(SalesOrder order,CancellationToken ct){var dto=mapper.Map<OrderDto>(order);dto.Lines=mapper.Map<IReadOnlyList<OrderLineDto>>(await uow.Lines.GetByOrderAsync(order.OrderId,ct));return dto;}
 // One UoW transaction writes SalesOrder and all OrderLine rows; price/name are read from the product snapshot.
 public async Task<OrderDto> CreateAsync(CreateOrderDto d,CancellationToken ct){await uow.BeginAsync(ct:ct);try{if(await uow.Customers.GetByIdAsync(d.CustomerId,ct)is null)throw new EntityNotFoundException($"Customer {d.CustomerId} was not found.");var order=await uow.Orders.AddAsync(new SalesOrder{CustomerId=d.CustomerId},ct);foreach(var requested in d.Lines){if(requested.Quantity is <1 or >99)throw new DomainValidationException("Line quantity must be between 1 and 99.");var product=await uow.Products.GetByIdAsync(requested.ProductId,ct)??throw new EntityNotFoundException($"Product {requested.ProductId} was not found.");await uow.Lines.AddAsync(new OrderLine{OrderId=order.OrderId,ProductId=product.ProductId,ProductNameSnapshot=product.ProductName,UnitPriceSnapshot=product.CurrentPrice,Quantity=requested.Quantity},ct);}await uow.CommitAsync(ct);return await GetAsync(order.OrderId,ct);}catch(SqlException e)when(e.Number is 2601 or 2627){await SafeRollback(ct);throw new BusinessConflictException("The order conflicts with an existing order line or record.");}catch{await SafeRollback(ct);throw;}}
 public async Task<OrderDto> ChangeStatusAsync(Guid id,UpdateOrderStatusDto d,CancellationToken ct){await uow.BeginAsync(ct:ct);try{var order=await uow.Orders.GetByIdAsync(id,ct)??throw new EntityNotFoundException($"Order {id} was not found.");var version=CustomerService.DecodeVersion(d.RowVersion);try{await uow.Orders.SetStatusAsync(id,d.Status,version,ct);}catch(SqlException e)when(e.Number is 51003 or 51004 or 51005){throw new BusinessConflictException(e.Message);}await uow.CommitAsync(ct);return await GetAsync(id,ct);}catch{await SafeRollback(ct);throw;}}
 public async Task DeleteAsync(Guid id,CancellationToken ct){await uow.BeginAsync(ct:ct);try{if(await uow.Orders.DeleteAsync(id,ct)==0)throw new EntityNotFoundException($"Order {id} was not found.");await uow.Lines.DeleteByOrderAsync(id,ct);await uow.CommitAsync(ct);}catch{await SafeRollback(ct);throw;}}
 private async Task SafeRollback(CancellationToken ct){try{await uow.RollbackAsync(ct);}catch{}}
}
